CREATE VIEW v50575 AS SELECT *, ST_OVERLAPS(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION())'), ST_GEOMFROMTEXT('POINT(0 0)')) AS x1, ST_EQUALS(ST_ENVELOPE(ST_GEOMFROMTEXT('POLYGON((0 0, 1 0, 2 0, 0 0))')), ST_GEOMFROMTEXT('POINT(0 0)')) AS x2 FROM v48981 AS x5 JOIN v50242 AS x6 ON x5.v48983 = x5.v48982 WHERE x6.v50243 <= '2005-01-01'